+/**
+ * These routes render a content-free application shell on the server. The
+ * writer's actual work remains in IndexedDB/Lix and is never copied into this
+ * cache. Dynamic public/share routes are deliberately absent.
+ */
+const WRITING_PATHS = new Set([
+  "/analysis/",
+  "/apparatus/",
+  "/desk/",
+  "/dossier/create/",
+  "/dossier/refine/",
+  "/editor/",
+  "/library/",
+  "/onboarding/",
+  "/personas/",
+  "/revisions/",
+  "/rubric/",
+  "/settings/",
+]);
+
+const INSTALL_PATHS = [
+  "/editor/",
+  "/dossier/create/",
+  "/manifest.json",
+  "/assets/griffin-mark.svg",
+  "/icon-192.png",
+  "/icon-512.png",
+  "/icon-512-maskable.png",
+];
+
+const CACHEABLE_ASSET_DESTINATIONS = new Set([
+  "font",
+  "image",
+  "manifest",
+  "script",
+  "style",
+  "worker",
+]);
+
+function canStore(response: Response): boolean {
+  if (!response.ok || response.type === "opaque") return false;
+  const cacheControl = response.headers.get("cache-control") ?? "";
+  return !/(?:^|,)\s*(?:no-store|private)\b/i.test(cacheControl);
+}
+
+async function fetchAndStore(
+  cache: Cache,
+  request: Request,
+): Promise<Response> {
+  const response = await fetch(request);
+  if (canStore(response)) {
+    await cache.put(request, response.clone());
+  }
+  return response;
+}
+
+async function networkFirst(request: Request): Promise<Response> {
+  const cache = await caches.open(CACHE_NAME);
+  try {
+    return await fetchAndStore(cache, request);
+  } catch (error) {
+    const cached = await cache.match(request, { ignoreSearch: true });
+    if (cached) return cached;
+    throw error;
+  }
+}
+
+async function cacheFirst(request: Request): Promise<Response> {
+  const cache = await caches.open(CACHE_NAME);
+  const cached = await cache.match(request);
+  if (cached) return cached;
+  return fetchAndStore(cache, request);
+}
+
+self.addEventListener("install", (event) => {
+  event.waitUntil(
+    (async () => {
+      const cache = await caches.open(CACHE_NAME);
+      await Promise.allSettled(
+        INSTALL_PATHS.map((path) =>
+          fetchAndStore(
+            cache,
+            new Request(new URL(path, self.location.origin), {
+              cache: "reload",
+            }),
+          ),
+        ),
+      );
+      await self.skipWaiting();
+    })(),
+  );
+});
+
+self.addEventListener("activate", (event) => {
+  event.waitUntil(
+    (async () => {
+      const names = await caches.keys();
+      await Promise.all(
+        names
+          .filter((name) => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME)
+          .map((name) => caches.delete(name)),
+      );
+      await self.clients.claim();
+    })(),
+  );
+});
+
+self.addEventListener("fetch", (event) => {
+  const { request } = event;
+  if (request.method !== "GET") return;
+
+  const url = new URL(request.url);
+  if (url.origin !== self.location.origin) return;
+
+  if (request.mode === "navigate" && WRITING_PATHS.has(url.pathname)) {
+    event.respondWith(networkFirst(request));
+    return;
+  }
+
+  if (CACHEABLE_ASSET_DESTINATIONS.has(request.destination)) {
+    event.respondWith(cacheFirst(request));
