+async function serveRootStaticFile(req, res, next) {
+  if (req.method !== "GET" && req.method !== "HEAD") return next();
+
+  const pathname = new URL(req.url ?? "/", "http://localhost").pathname;
+  let filename;
+  try {
+    filename = decodeURIComponent(pathname.slice(1));
